	public static readonly string DATA_ALIGNMENT = "Data Alignment";
	public static readonly int DATA_ALIGNMENT_DEFAULT = 1;

	public static readonly string SKIP_HOMOGENOUS_DATA = "Skip Homogenous Data";
	public static readonly bool SKIP_HOMOGENOUS_DATA_DEFAULT = true;

